declare_lint ! { # [doc = " The `mismatched_lifetime_syntaxes` lint detects when the same"] # [doc = " lifetime is referred to by different syntaxes between function"] # [doc = " arguments and return values."] # [doc = ""] # [doc = " The three kinds of syntaxes are:"] # [doc = ""] # [doc = " 1. Named lifetimes. These are references (`&'a str`) or paths"] # [doc = "    (`Person<'a>`) that use a lifetime with a name, such as"] # [doc = "    `'static` or `'a`."] # [doc = ""] # [doc = " 2. Elided lifetimes. These are references with no explicit"] # [doc = "    lifetime (`&str`), references using the anonymous lifetime"] # [doc = "    (`&'_ str`), and paths using the anonymous lifetime"] # [doc = "    (`Person<'_>`)."] # [doc = ""] # [doc = " 3. Hidden lifetimes. These are paths that do not contain any"] # [doc = "    visual indication that it contains a lifetime (`Person`)."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,compile_fail"] # [doc = " #![deny(mismatched_lifetime_syntaxes)]"] # [doc = ""] # [doc = " pub fn mixing_named_with_elided(v: &'static u8) -> &u8 {"] # [doc = "     v"] # [doc = " }"] # [doc = ""] # [doc = " struct Person<'a> {"] # [doc = "     name: &'a str,"] # [doc = " }"] # [doc = ""] # [doc = " pub fn mixing_hidden_with_elided(v: Person) -> Person<'_> {"] # [doc = "     v"] # [doc = " }"] # [doc = ""] # [doc = " struct Foo;"] # [doc = ""] # [doc = " impl Foo {"] # [doc = "     // Lifetime elision results in the output lifetime becoming"] # [doc = "     // `'static`, which is not what was intended."] # [doc = "     pub fn get_mut(&'static self, x: &mut u8) -> &mut u8 {"] # [doc = "         unsafe { &mut *(x as *mut _) }"] # [doc = "     }"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " Lifetime elision is useful because it frees you from having to"] # [doc = " give each lifetime its own name and show the relation of input"] # [doc = " and output lifetimes for common cases. However, a lifetime"] # [doc = " that uses inconsistent syntax between related arguments and"] # [doc = " return values is more confusing."] # [doc = ""] # [doc = " In certain `unsafe` code, lifetime elision combined with"] # [doc = " inconsistent lifetime syntax may result in unsound code."] pub MISMATCHED_LIFETIME_SYNTAXES , Warn , "detects when a lifetime uses different syntax between arguments and return values" }